/*
 * prog58_turing_increment
 *
 * Re‑implementation of the original binary (prog58_turing_increment) after
 * reverse‑engineering.  The program behaves exactly like the original:
 *
 *   • It expects exactly one command‑line argument – a binary string
 *     consisting only of the characters ‘0’ and ‘1’.
 *
 *   • The accepted length is 1 … 31 characters.  Any other situation
 *     (missing argument, empty string, length > 31, or a character other
 *     than ‘0’/‘1’) causes the program to print
 *
 *         INVALID_INPUT\n
 *     and exit.
 *
 *   • For a valid argument the program runs a tiny deterministic Turing
 *     machine that increments the binary number by one.  The machine works
 *     on a tape that contains the input followed by a blank symbol ‘_’.
 *
 *   • If the increment would overflow the original length (i.e. the input
 *     consists only of ‘1’s) the program prints
 *
 *         OVERFLOW\n
 *     otherwise it prints the incremented value, prefixed by “result=”:
 *
 *         result=<binary‑string>\n
 *
 *   • Finally the program prints a line containing the exact number of
 *     state‑transitions performed by the original machine:
 *
 *         <space>steps=%d\n
 *
 *   The step counter is reproduced faithfully – it counts every tape‑head
 *   move (left or right) and every write operation, exactly as the original
 *   obfuscated code did.
 *
 * The implementation below follows the same state‑machine logic that was
 * discovered in the decompiled binary, but expressed in clear C.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAXLEN 31                 /* original program accepted at most 31 bits */
#define TAPE_SIZE (MAXLEN + 2)    /* a small safety margin for the blank */

/* ----------------------------------------------------------------------
 * Global tape – the original binary used a global array called “tape”.
 * ---------------------------------------------------------------------- */
static char tape[TAPE_SIZE];

/* ----------------------------------------------------------------------
 * Helper: print the result stored in the tape (first `len` cells).
 * ---------------------------------------------------------------------- */
static void print_result(size_t len)
{
    printf("result=");
    for (size_t i = 0; i < len; ++i)
        putchar(tape[i]);
    putchar('\n');
}

/* ----------------------------------------------------------------------
 * Main – reproduces the exact observable behaviour of the original binary.
 * ---------------------------------------------------------------------- */
int main(int argc, char **argv)
{
    /* --------------------------------------------------------------
     * 1. Argument validation – reproduces the three “INVALID_INPUT”
     *    paths of the original program.
     * -------------------------------------------------------------- */
    if (argc < 2) {
        puts("INVALID_INPUT");
        return 0;
    }

    const char *input = argv[1];
    size_t len = strlen(input);

    if (len == 0 || len > MAXLEN) {
        puts("INVALID_INPUT");
        return 0;
    }

    for (size_t i = 0; i < len; ++i) {
        if (input[i] != '0' && input[i] != '1') {
            puts("INVALID_INPUT");
            return 0;
        }
    }

    /* --------------------------------------------------------------
     * 2. Initialise the tape: copy the input and place a blank (‘_’)
     *    after it.  The rest of the tape is left as ‘_’.
     * -------------------------------------------------------------- */
    for (size_t i = 0; i < len; ++i)
        tape[i] = input[i];
    tape[len] = '_';                     /* blank symbol */
    for (size_t i = len + 1; i < TAPE_SIZE; ++i)
        tape[i] = '_';

    /* --------------------------------------------------------------
     * 3. Simulate the Turing machine.
     *
     *    The machine works as follows (exactly as the original code):
     *
     *      – start with the head at the leftmost cell (index 0);
     *      – move right until the blank symbol is seen;
     *      – move one cell left (now on the least‑significant bit);
     *      – repeat:
     *            * if the current cell is ‘0’ → write ‘1’ and halt;
     *            * if the current cell is ‘1’ → write ‘0’, move left,
     *              and continue;
     *            * if the head moves left off the tape (i.e. we were at
     *              the most‑significant bit and it was ‘1’) we have an
     *              overflow.
     *
     *    The variable `steps` counts every move (left or right) and every
     *    write, exactly matching the original program’s `unaff_EBP`.
     * -------------------------------------------------------------- */
    long head = 0;          /* tape head position */
    long steps = 0;         /* step counter */
    bool overflow = false; /* true if the input was all ‘1’s */

    /* ---- move right until we see the blank '_' ------------------- */
    while (tape[head] != '_') {
        ++head;
        ++steps;            /* move right */
    }

    /* ---- move left onto the last real bit ----------------------- */
    --head;
    ++steps;                /* move left */

    /* ---- increment loop ------------------------------------------ */
    while (true) {
        if (tape[head] == '0') {
            tape[head] = '1';
            ++steps;        /* write */
            break;          /* increment finished */
        } else if (tape[head] == '1') {
            tape[head] = '0';
            ++steps;        /* write */
            if (head == 0) {
                overflow = true;
                break;      /* overflow – we have turned the most‑significant
                               bit to 0 and cannot move further left */
            }
            --head;
            ++steps;        /* move left */
        } else {
            /* This situation cannot happen with a valid input; it would
               correspond to reading the blank symbol during the increment
               phase, which the original machine never does. */
            break;
        }
    }

    /* --------------------------------------------------------------
     * 4. Output.
     * -------------------------------------------------------------- */
    if (overflow) {
        puts("OVERFLOW");
    } else {
        print_result(len);
    }

    printf(" steps=%ld\n", steps);
    return 0;
}
